const event = $input.first().json.event || $input.first().json;
const payload = event.payload || {};

const systemPrompt = `Eres el evaluador metodológico de experimentos de RAX.\nTu labor es contrastar la evidencia y los datos observados con los criterios de éxito y refutación fijados de antemano.\nREGLAS IMPERATIVAS:\n1. Compara estrictamente lo observado (observedMetric) contra los criterios previstos.\n2. Clasifica el resultado en uno de estos estados: 'supported', 'weakened', 'mixed', 'inconclusive', 'evidence_insufficient'.\n3. No intentes maquillar resultados negativos; un aprendizaje de refutación ahorra meses de trabajo.\n4. Si los datos aportados no son suficientes para concluir, declara 'evidence_insufficient' en lugar de adivinar.\n5. Salida en JSON estricto con: evaluatedOutcome (string), observedVsPlanned (string), keyLearnings (string), limitations (string), recommendedNextStep (string), uncertainties (array de strings).`;

const userPrompt = JSON.stringify({
  experimentId: event.entityId,
  hypothesisStatement: payload.hypothesisStatement,
  metricPlanned: payload.metric,
  successCriterion: payload.successCriterion,
  rejectionCriterion: payload.rejectionCriterion,
  observedValue: payload.metricValue || payload.observed,
  evidenceNotes: payload.evidenceNotes || payload.learnings || ''
});

return [{
  json: {
    correlationId: event.correlationId || 'corr_' + Date.now(),
    callbackUrl: event.callback?.url || ($env.RAX_API_URL || 'https://rax-red.vercel.app') + '/api/n8n/callback',
    model: $env.OPENROUTER_MODEL || 'meta-llama/llama-3.3-70b-instruct:free',
    apiKey: $env.OPENROUTER_API_KEY || '',
    systemPrompt,
    userPrompt
  }
}];

